from collections import defaultdict

class Solution:

	def dupSub(self, root):
		d = defaultdict(int)

		def dfs(root):
			if not root:
				return 'X'
			res = ''
			if not root.left and (not root.right):
				res = str(root.data)
				return res
			res += str(root.data) + '-' + dfs(root.left) + '-' + dfs(root.right)
			d[res] += 1
			return res
		dfs(root)
		for x in d:
			if d[x] > 1:
				return 1
		return 0
